package com.relayaegis.remediation.github;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Deterministic remediation branch names: relay-aegis/fix/&lt;finding-id&gt;, then -2, -3 … when taken. The finding ID is
 * generated by RELAY AEGIS, but it is still reduced to a strict character set so no input can shape the ref.
 */
public final class RemediationBranchNames {
    public static final String PREFIX = "relay-aegis/fix/";
    public static final int MAX_ATTEMPTS = 20;
    private static final Pattern SAFE = Pattern.compile("[A-Za-z0-9][A-Za-z0-9-]{0,59}");

    private RemediationBranchNames() {}

    public static String base(String findingId) {
        String cleaned = findingId == null ? "" : findingId.replaceAll("[^A-Za-z0-9-]", "-").replaceAll("-{2,}", "-").replaceAll("^-+|-+$", "");
        if (cleaned.length() > 60) cleaned = cleaned.substring(0, 60);
        if (!SAFE.matcher(cleaned).matches()) throw new IllegalArgumentException("The finding ID cannot form a safe branch name.");
        return PREFIX + cleaned;
    }

    /** attempt 1 = base name; attempt n &gt; 1 = base-n. */
    public static String candidate(String findingId, int attempt) {
        return attempt <= 1 ? base(findingId) : base(findingId) + "-" + attempt;
    }

    /** True only for names this class could have produced (used to refuse anything else before a write). */
    public static boolean isRemediationBranch(String branch) {
        return branch != null && branch.startsWith(PREFIX) && branch.substring(PREFIX.length()).matches("[A-Za-z0-9][A-Za-z0-9-]{0,63}")
                && !branch.toLowerCase(Locale.ROOT).endsWith(".lock");
    }
}
